from collections import Counter

class Solution:
    def rearrangeCharacters(self, s: str, target: str) -> int:
        s_cnt = Counter(s)
        t_cnt = Counter(target)
        return min(s_cnt[ch] // t_cnt[ch] for ch in t_cnt)

class Solution {
public:
    int rearrangeCharacters(std::string s, std::string target) {
        std::vector<int> s_cnt(26, 0), t_cnt(26, 0);
        for (char c : s) s_cnt[c - 'a']++;
        for (char c : target) t_cnt[c - 'a']++;
        int ans = 1e9;
        for (int i = 0; i < 26; ++i) {
            if (t_cnt[i] > 0) {
                ans = std::min(ans, s_cnt[i] / t_cnt[i]);
            }
        }
        return ans;
    }
};

class Solution {
    public int rearrangeCharacters(String s, String target) {
        int[] sCnt = new int[26];
        int[] tCnt = new int[26];
        for (char c : s.toCharArray()) sCnt[c - 'a']++;
        for (char c : target.toCharArray()) tCnt[c - 'a']++;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < 26; i++) {
            if (tCnt[i] > 0) {
                ans = Math.min(ans, sCnt[i] / tCnt[i]);
            }
        }
        return ans;
    }
}

var rearrangeCharacters = function(s, target) {
    const sCnt = new Int32Array(26);
    const tCnt = new Int32Array(26);
    for (let i = 0; i < s.length; i++) sCnt[s.charCodeAt(i) - 97]++;
    for (let i = 0; i < target.length; i++) tCnt[target.charCodeAt(i) - 97]++;
    let ans = Infinity;
    for (let i = 0; i < 26; i++) {
        if (tCnt[i] > 0) {
            ans = Math.min(ans, Math.floor(sCnt[i] / tCnt[i]));
        }
    }
    return ans;
};
